    /* Wait a bit longer until the workers have picked up the dispatched callback */
    UA_realSleep(100);
    ck_assert_uint_eq(*executed, true);

    UA_Server_removeRepeatedCallback(server, id);
    UA_Boolean_delete(executed);
}
